import heapq
from collections import defaultdict


def topo_order(n, edges):
    graph = defaultdict(list)
    indegree = [0] * (n + 1)
    for before, after in edges:
        graph[before].append(after)
        indegree[after] += 1
    ready = [node for node in range(1, n + 1) if indegree[node] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for nxt in graph[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)
    return order


plans = [
    [(3, 1), (3, 2), (1, 4), (2, 4), (5, 2)],
    [(1, 2), (2, 3), (3, 1), (4, 5)],
]
n = 5
for i, edges in enumerate(plans, start=1):
    order = topo_order(n, edges)
    if len(order) < n:
        print(f"Plan {i}: cycle")
    else:
        print(f"Plan {i}:", " -> ".join(map(str, order)))

import heapq
import math
from collections import defaultdict


def dijkstra(graph, nodes, source):
    dist = {node: math.inf for node in nodes}
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist[node]:
            continue
        for nbr, w in graph[node]:
            if d + w < dist[nbr]:
                dist[nbr] = d + w
                heapq.heappush(heap, (dist[nbr], nbr))
    return dist


roads = [("A", "B", 4), ("A", "C", 1), ("C", "B", 2),
         ("B", "D", 5), ("C", "D", 8), ("E", "D", 1)]
graph = defaultdict(list)
for u, v, w in roads:
    graph[u].append((v, w))

dist = dijkstra(graph, ["A", "B", "C", "D", "E"], "A")
for node, d in dist.items():
    print(f"{node}: {d if d != math.inf else 'unreachable'}")
